def compute(vars):
    total_assets = vars["Total Assets"]
    total_liabilities = vars["Total Liabilities"]

    total_assets_billion = total_assets / 1000.0
    total_liabilities_billion = total_liabilities
    total_shareholders_equity = (
        total_assets_billion - total_liabilities_billion
    )

    return {
        "value": total_shareholders_equity,
        "trace": {
            "Total Assets": total_assets,
            "Total Liabilities": total_liabilities,
            "Total Assets (billion)": total_assets_billion,
            "Total Liabilities (billion)": total_liabilities_billion,
            "output_meta": {
                "currency": "$",
                "scale": "billion",
                "unit": None
            }
        }
    }
